67	    ///
68	    /// assert_eq!(Case::identify("HTTPSERVER", /* no effect */ true), Case::Upper);
69	    ///
70	    /// assert_eq!(Case::identify("100", /* no effect */ true), Case::Uni);
71	    /// assert_eq!(Case::identify("안녕하세요", /* no effect */ true), Case::Uni);
